#!/usr/bin/env node
/**
 * SJ Maths UP TGT/PGT General Knowledge topic generator.
 *
 * Generates one complete, crawlable index.html per static GK topic with:
 *   1. Study Notes
 *   2. Concept Quiz covering every supported question type for every concept
 *   3. Detailed Revision Summary
 *   4. Ten-question Topic Test
 *
 * Current Affairs is intentionally excluded. It needs a separate dated,
 * source-backed content format and must never enter this static-topic batch.
 *
 * Examples:
 *   node scripts/generate_up_tgt_pgt_gk.mjs --dry-run
 *   node scripts/generate_up_tgt_pgt_gk.mjs --module indian-history --limit 1
 *   node scripts/generate_up_tgt_pgt_gk.mjs --topic /up-tgt-pgt-gk/indian-history/indus-valley/ --force
 *   node scripts/generate_up_tgt_pgt_gk.mjs --topic /up-tgt-pgt-gk/indian-history/1857-revolt/ --force
 */

import fs from 'node:fs';
import path from 'node:path';
import 'dotenv/config';
import { GoogleGenAI } from '@google/genai';
import { jsonrepair } from 'jsonrepair';

const ROOT = process.cwd();
const GK_ROOT = path.join(ROOT, 'up-tgt-pgt-gk');
const STATUS_PATH = path.join(ROOT, 'content-generation-status-up-tgt-pgt-gk.json');
const MODEL = process.env.GEMINI_MODEL || 'gemini-3.5-flash-lite';
const CONTENT_VERSION = 'depth-v2';
const QUESTION_TYPES = ['mcq', 'assertion_reason', 'true_false', 'fill_blank', 'match_following', 'case_based', 'short_answer'];
const STATIC_MODULES = ['indian-history', 'indian-polity', 'geography', 'general-science', 'art-culture', 'economy'];
const CURRENT_AFFAIRS_MODULE = 'current-affairs';
const MODULE_TITLES = {
  'indian-history': 'Indian History',
  'indian-polity': 'Indian Polity and Constitution',
  geography: 'Geography',
  'general-science': 'General Science',
  'art-culture': 'Indian Art and Culture',
  economy: 'Indian Economy'
};

const args = process.argv.slice(2);
const hasFlag = (flag) => args.includes(flag);
function argValue(flag) {
  const index = args.indexOf(flag);
  return index >= 0 ? args[index + 1] : null;
}

const requestedTopic = argValue('--topic');
const requestedModule = argValue('--module');
const dryRun = hasFlag('--dry-run');
const allFlag = hasFlag('--all');
const force = hasFlag('--force');
const useGemini = hasFlag('--gemini') || hasFlag('--api') || allFlag;
const maxAttempts = Math.max(1, Number.parseInt(argValue('--attempts') || '2', 10) || 2);
const limit = Math.max(0, Number.parseInt(argValue('--limit') || '0', 10) || 0);
const gapMs = Math.max(0, Number.parseInt(argValue('--gap') || '0', 10) || 0) * 1000;

function decodeHtml(value) {
  return String(value || '')
    .replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ')
    .replace(/&#(d+);/g, (_, code) => String.fromCodePoint(Number(code)))
    .replace(/&#x([\da-f]+);/gi, (_, code) => String.fromCodePoint(Number.parseInt(code, 16)))
    .replace(/\s+/g, ' ').trim();
}

function stripTags(value) { return decodeHtml(String(value || '').replace(/<[^>]*>/g, ' ')); }

function normalizeUrl(value) {
  let url = String(value || '').trim().replace(/\\/g, '/');
  if (!url.startsWith('/')) url = `/${url}`;
  if (!url.endsWith('/')) url += '/';
  return url.replace(/\/index\.html\/$/, '/');
}

function urlToDir(url) { return path.join(ROOT, url.replace(/^\//, '').replace(/\/$/, '')); }

function slugFromKey(key, title) {
  const keyPart = String(key || '').split('/').filter(Boolean).at(-1);
  if (keyPart) return keyPart.toLowerCase();
  return String(title || 'topic').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}

function titleFromSlug(slug) {
  return String(slug || '').split('-').map((word) => word ? word[0].toUpperCase() + word.slice(1) : word).join(' ');
}

function readStatus() {
  if (!fs.existsSync(STATUS_PATH)) return {};
  try { return JSON.parse(fs.readFileSync(STATUS_PATH, 'utf8')); } catch { return {}; }
}

function writeStatus(status) {
  try { fs.writeFileSync(STATUS_PATH, `${JSON.stringify(status, null, 2)}\n`, 'utf8'); }
  catch (error) { console.warn(`Warning: could not update status log (${error.code || error.message}); continuing.`); }
}

function parseTrackerTopics(moduleKey) {
  const modulePath = path.join(GK_ROOT, moduleKey, 'index.html');
  if (!fs.existsSync(modulePath)) return [];
  const html = fs.readFileSync(modulePath, 'utf8');
  const topics = [];
  const topicRegex = /<div\s+class="topic"([^>]*)>([\s\S]*?)<\/div>\s*(?=<div\s+class="topic"|<\/div>\s*<\/div>)/gi;
  let match;
  while ((match = topicRegex.exec(html))) {
    const attrs = match[1];
    const body = match[2];
    const key = attrs.match(/data-key="([^"]+)"/i)?.[1] || '';
    const search = attrs.match(/data-search="([^"]*)"/i)?.[1] || '';
    const title = stripTags(body.match(/class="topic-title"[^>]*>([\s\S]*?)<\/span>/i)?.[1] || '');
    const description = stripTags(body.match(/class="topic-desc"[^>]*>([\s\S]*?)<\/span>/i)?.[1] || '');
    if (!key || !title) continue;
    const slug = slugFromKey(key, title);
    topics.push({
      module: moduleKey,
      moduleTitle: MODULE_TITLES[moduleKey] || titleFromSlug(moduleKey),
      key,
      slug,
      topicName: title,
      description,
      search,
      url: normalizeUrl(`/up-tgt-pgt-gk/${moduleKey}/${slug}/`)
    });
  }
  return topics;
}

function discoverTopics() {
  return STATIC_MODULES.flatMap(parseTrackerTopics)
    .sort((a, b) => a.url.localeCompare(b.url));
}

function resolveTargets(allTopics) {
  if (requestedModule === CURRENT_AFFAIRS_MODULE) {
    throw new Error('Current Affairs is excluded from this generator. Use a separate current-affairs generator.');
  }
  if (requestedModule && !STATIC_MODULES.includes(requestedModule)) {
    throw new Error(`Unsupported static GK module: ${requestedModule}. Allowed: ${STATIC_MODULES.join(', ')}`);
  }
  let targets = allTopics;
  if (requestedModule) targets = targets.filter((topic) => topic.module === requestedModule);
  if (requestedTopic) {
    const url = normalizeUrl(requestedTopic);
    if (url.includes('/current-affairs/')) throw new Error('Current Affairs is excluded from this generator.');
    const found = allTopics.find((topic) => topic.url === url);
    if (!found) throw new Error(`Static GK topic not found in a tracker module: ${url}`);
    if (!CURATED_CONTENT[found.slug] && !useGemini && !dryRun) throw new Error(`No manually authored content exists yet for ${url}. Use --gemini to generate this remaining topic with ${MODEL}.`);
    targets = [found];
  } else if (!dryRun && !allFlag && !requestedModule) {
    throw new Error('Manual mode requires one --topic at a time. Add content for that topic before generating it.');
  }
  return limit > 0 ? targets.slice(0, limit) : targets;
}

function requireText(value, label) {
  if (typeof value !== 'string' || !value.trim()) throw new Error(`${label} must be a non-empty string`);
}

function validateQuestion(question, label, allowShort = true) {
  requireText(question?.id, `${label}.id`);
  requireText(question?.concept_id, `${label}.concept_id`);
  requireText(question?.type, `${label}.type`);
  requireText(question?.question, `${label}.question`);
  requireText(question?.explanation, `${label}.explanation`);
  if (!QUESTION_TYPES.includes(question.type)) throw new Error(`${label} has unsupported type ${question.type}`);
  if (question.type === 'fill_blank') {
    if (!Array.isArray(question.accepted_answers) || !question.accepted_answers.length) throw new Error(`${label} needs accepted_answers`);
  } else if (question.type === 'short_answer') {
    if (!allowShort) throw new Error(`${label} cannot be short_answer`);
    requireText(question.expected_answer, `${label}.expected_answer`);
  } else if (!Array.isArray(question.options) || question.options.length < 2 || !Number.isInteger(question.correct_index) || question.correct_index < 0 || question.correct_index >= question.options.length) {
    throw new Error(`${label} needs valid options and correct_index`);
  }
}

function validatePayload(data, { deep = false } = {}) {
  if (!data || !Array.isArray(data.concepts) || data.concepts.length === 0) throw new Error('content must contain at least one concept; choose the number required by the topic');
  requireText(data.title, 'title');
  const introductionMinimum = 4;
  if (!Array.isArray(data.introduction_points) || data.introduction_points.length < introductionMinimum) throw new Error(`introduction_points needs at least ${introductionMinimum} items`);
  const ids = new Set();
  for (const [index, concept] of data.concepts.entries()) {
    requireText(concept.id, `concept ${index + 1}.id`);
    requireText(concept.title, `concept ${index + 1}.title`);
    requireText(concept.lead, `concept ${concept.id}.lead`);
    if (ids.has(concept.id)) throw new Error(`duplicate concept id ${concept.id}`);
    ids.add(concept.id);
    const requirements = deep
      ? [['prerequisite_points', 1], ['definition_points', 2], ['explanation_points', 6], ['key_points', 4], ['worked_examples', 1], ['applications', 2], ['advanced_points', 2], ['examples', 2], ['comparison_points', 2], ['common_misconceptions', 2], ['exam_focus_points', 3]]
      : [['explanation_points', 5], ['key_points', 4], ['examples', 2], ['comparison_points', 2], ['common_misconceptions', 2], ['exam_focus_points', 3]];
    for (const [field, minimum] of requirements) {
      if (!Array.isArray(concept[field]) || concept[field].length < minimum) throw new Error(`concept ${concept.id} needs ${minimum} ${field}`);
      concept[field].forEach((item, itemIndex) => requireText(item, `${concept.id}.${field}[${itemIndex}]`));
    }
  }
  const revision = data.revision;
  if (!revision || !Array.isArray(revision.concept_revisions) || revision.concept_revisions.length !== data.concepts.length) throw new Error('revision needs one detailed entry for every concept');
  const revisionIds = new Set();
  revision.concept_revisions.forEach((item) => {
    requireText(item.concept_id, 'revision concept_id');
    if (!ids.has(item.concept_id) || revisionIds.has(item.concept_id)) throw new Error(`invalid or duplicate revision concept ${item.concept_id}`);
    revisionIds.add(item.concept_id);
    requireText(item.title, `revision ${item.concept_id}.title`);
    const revisionRequirements = deep ? [['definition_points', 2], ['must_remember', 4], ['exam_traps', 2]] : [['definition_points', 3], ['must_remember', 5], ['exam_traps', 2]];
    for (const [field, minimum] of revisionRequirements) {
      if (!Array.isArray(item[field]) || item[field].length < minimum) throw new Error(`revision ${item.concept_id} needs ${minimum} ${field}`);
      item[field].forEach((point, index) => requireText(point, `${item.concept_id}.${field}[${index}]`));
    }
  });
  for (const [field, minimum] of [['quick_facts', 5], ['glossary', 4], ['comparisons', 1], ['memory_hooks', 3], ['exam_traps', 4]]) {
    if (!Array.isArray(revision[field]) || revision[field].length < minimum) throw new Error(`revision needs ${minimum} ${field}`);
  }
  if (!Array.isArray(data.quiz_questions) || data.quiz_questions.length < data.concepts.length * QUESTION_TYPES.length) throw new Error(`quiz needs at least ${data.concepts.length * QUESTION_TYPES.length} questions`);
  const coverage = new Map(data.concepts.map((concept) => [concept.id, new Set()]));
  data.quiz_questions.forEach((question, index) => {
    validateQuestion(question, `quiz ${index + 1}`);
    if (!coverage.has(question.concept_id)) throw new Error(`quiz ${question.id} references an unknown concept`);
    coverage.get(question.concept_id).add(question.type);
  });
  for (const [id, types] of coverage) {
    const missing = QUESTION_TYPES.filter((type) => !types.has(type));
    if (missing.length) throw new Error(`concept ${id} is missing quiz types: ${missing.join(', ')}`);
  }
  if (!Array.isArray(data.topic_test) || data.topic_test.length !== 10) throw new Error('topic_test must contain exactly 10 questions');
  data.topic_test.forEach((question, index) => {
    if (!['mcq', 'assertion_reason', 'match_following', 'case_based'].includes(question.type)) throw new Error(`test ${index + 1} must be objective`);
    validateQuestion(question, `test ${index + 1}`, false);
    if (!coverage.has(question.concept_id)) throw new Error(`test ${question.id} references an unknown concept`);
  });
  return data;
}

function parseJson(raw) {
  const cleaned = String(raw || '').trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
  try { return JSON.parse(cleaned); }
  catch (firstError) {
    try { return JSON.parse(jsonrepair(cleaned)); }
    catch { throw new Error(`Gemini JSON parse failed: ${firstError.message}`); }
  }
}

function buildPrompt(topic) {
  return `You are an expert Indian General Studies professor and UP TGT/PGT examiner.
Create a complete, accurate learning page for this static GK topic.

Subject module: ${topic.moduleTitle}
Topic: ${topic.topicName}
Topic description from the syllabus tracker: ${topic.description || topic.search || topic.topicName}
Canonical URL: ${topic.url}
Audience: UP TGT and UP PGT aspirants.

Content rules:
- Build an exhaustive concept map before writing. Include as many concepts as this topic genuinely requires; there is no fixed minimum or maximum concept count. Do not pad a small topic or merge distinct syllabus subtopics just to reduce the count.
- Order concepts from prerequisites and foundations to core principles, classifications or chronology, worked applications, advanced extensions and examination synthesis. Cover every important subtopic named or implied by the syllabus description.
- Study notes must be point-wise, not long paragraphs. Use short, standalone points with one idea per bullet, but explain each idea fully enough for a learner to progress from basic understanding to advanced application.
- Include definitions, prerequisites, terminology, mechanisms or chronology, step-by-step examples, applications, exceptions/limitations, comparisons, misconceptions and exam-level synthesis wherever relevant.
- The revision summary must include one detailed point-wise revision entry for every concept; do not merge concepts.
- Use exact dates, constitutional Articles, places, persons, terms and scientific facts only when established and reliable.
- Distinguish similar terms clearly and include UP-relevant facts when naturally relevant.
- For chronology-, movement-, ruler-, leader-, site- or institution-heavy topics, include a complete optional movement_table with the major entries; do not omit established syllabus items. For other topics, return an empty movement_table.
- Do not include current affairs, changing office-holders, current rankings, recent schemes or time-sensitive news.
- Do not invent PYQ years or citations.
- Return JSON only. No Markdown fences, HTML or commentary.

Return exactly this JSON shape:
{
  "title": "SEO-friendly title",
  "short_title": "short topic title",
  "introduction_points": ["4 or more concise overview points"],
  "movement_table": [{"movement":"event, movement, person, site or feature", "period":"date or period", "founders":"founders if relevant", "leaders":"leaders, region or association", "key_points":"concise examination points"}],
  "movement_table_meta": {"title":"table title", "caption":"table caption", "first_header":"first column heading", "people_header":"people or association heading", "key_header":"key points heading"},
  "concepts": [
    {
      "id": "stable-kebab-case-id",
      "title": "Concept heading",
      "learning_stage": "foundation|core|application|advanced|exam-synthesis",
      "lead": "One-sentence central idea",
      "prerequisite_points": ["Prerequisite knowledge or terms needed before this concept"],
      "definition_points": ["Precise definitions, scope and terminology"],
      "explanation_points": ["At least 8 ordered point-wise explanations from basic to advanced"],
      "key_points": ["At least 6 precise recall points"],
      "worked_examples": ["At least 2 step-by-step worked examples, applications or chronological illustrations"],
      "applications": ["At least 3 practical, scientific, historical, constitutional or examination applications"],
      "advanced_points": ["At least 3 advanced extensions, exceptions, limitations or analytical points"],
      "examples": ["At least 3 short examples or illustrations"],
      "comparison_points": ["At least 3 point-wise distinctions from related ideas"],
      "common_misconceptions": ["At least 3 likely exam misconceptions"],
      "exam_focus_points": ["At least 5 exam-focused points"]
    }
  ],
  "revision": {
    "concept_revisions": [{
      "concept_id": "exact concept id",
      "title": "concept title",
      "definition_points": ["3 or more definition/scope points"],
      "must_remember": ["5 or more minute rapid-recall points"],
      "exam_traps": ["2 or more concept-specific traps"]
    }],
    "quick_facts": ["5 or more rapid-recall facts"],
    "glossary": [{"term":"term", "definition":"short accurate definition"}],
    "comparisons": [{"left":"concept A", "right":"concept B", "difference_points":["2 or more distinctions"]}],
    "memory_hooks": ["3 or more useful memory hooks"],
    "exam_traps": ["4 or more common traps or cautions"]
  },
  "quiz_questions": [{
    "id":"q-001", "concept_id":"concept-id", "type":"mcq|assertion_reason|true_false|fill_blank|match_following|case_based|short_answer",
    "question":"question text", "options":["A","B","C","D"], "correct_index":0,
    "accepted_answers":["answer"], "expected_answer":"answer", "explanation":"why this is correct"
  }],
  "topic_test": [{"id":"t-001", "concept_id":"concept-id", "type":"mcq", "question":"question", "options":["A","B","C","D"], "correct_index":0, "explanation":"why this is correct"}]
}

Quiz requirements:
- Generate one complete question set for every concept you created. The number of concepts must be determined by the topic, not by an artificial limit.
- Generate at least one question of every listed question type for every concept: ${QUESTION_TYPES.join(', ')}.
- For fill_blank use accepted_answers and no options. For short_answer use expected_answer and no options.
- For all objective types use plausible options, correct_index and explanations.
- Create exactly 10 objective topic_test questions using only mcq, assertion_reason, match_following or case_based.
- Keep all explanations concise, factual and useful for learning.`;
}

