function buildManualQuizQuestions(topic) {
  const specs = MANUAL_QUIZ_BANK[topic.slug];
  if (!Array.isArray(specs)) return [];
  const types = ['mcq', 'assertion_reason', 'true_false', 'fill_blank', 'match_following', 'case_based', 'short_answer'];
  let number = 1;
  return specs.flatMap((spec) => types.map((type) => {
    const source = spec[type];
    const question = { id: `q-${String(number++).padStart(3, '0')}`, concept_id: spec.concept_id, type, question: source.question, explanation: source.explanation };
    if (type === 'fill_blank') question.accepted_answers = source.accepted_answers;
    else if (type === 'short_answer') question.expected_answer = source.expected_answer;
    else { question.options = source.options; question.correct_index = source.correct_index; }
    return question;
  }));
}

function buildGenericQuizQuestions(topic, concepts) {
  const questions = [];
  let number = 1;
  for (const concept of concepts) {
    const answer = concept.key_points[0];
    for (const type of QUESTION_TYPES) {
      const id = `q-${String(number++).padStart(3, '0')}`;
      if (type === 'fill_blank') questions.push({ id, concept_id: concept.id, type, question: `Fill in the blank: The central recall point for ${concept.title} is ________.`, accepted_answers: [answer], explanation: `Review the key point: ${answer}` });
      else if (type === 'short_answer') questions.push({ id, concept_id: concept.id, type, question: `State one important examination point about ${concept.title}.`, expected_answer: answer, explanation: `A correct answer should include: ${answer}` });
      else {
        const options = [answer, `A distractor related to a different part of ${topic.topicName}`, 'An unrelated statement', 'A time-sensitive current-affairs claim'];
        if (type === 'true_false') { options[0] = 'True'; options[1] = 'False'; }
        questions.push({ id, concept_id: concept.id, type, question: type === 'case_based' ? `Case: A learner is revising ${concept.title}. Which response best applies the topic?` : `Which statement best represents ${concept.title}?`, options, correct_index: 0, explanation: `The correct choice reflects the topic point: ${answer}` });
      }
    }
  }
  return questions;
}

function buildGenericTopicTest(topic, concepts) {
  return Array.from({ length: 10 }, (_, index) => {
    const concept = concepts[index % concepts.length];
    return { id: `t-${String(index + 1).padStart(3, '0')}`, concept_id: concept.id, type: index % 4 === 1 ? 'assertion_reason' : index % 4 === 2 ? 'match_following' : index % 4 === 3 ? 'case_based' : 'mcq', question: `Test ${index + 1}: Which option is most accurate for ${concept.title}?`, options: [concept.key_points[0], 'This statement belongs to another topic', 'This is an unsupported conclusion', 'This is a current-affairs-only statement'], correct_index: 0, explanation: `The answer follows the key point: ${concept.key_points[0]}` };
  });
}

function makeOfflineConcepts(topic) {
  const base = topic.description || topic.search || `Core themes of ${topic.topicName}`;
  const labels = ['Meaning and scope', 'Key facts and classification', 'Indian and UP context', 'Exam comparisons and applications'];
  return labels.map((label, index) => ({
    id: `${topic.slug}-${label.toLowerCase().replace(/[^a-z]+/g, '-')}`.replace(/-+$/g, ''),
    title: `${topic.topicName}: ${label}`,
    lead: `${label} of ${topic.topicName} using the syllabus focus: ${base}.`,
    explanation_points: [
      `${topic.topicName} is studied under ${topic.moduleTitle} for UP TGT and UP PGT examinations.`,
      `The tracker identifies these focus areas: ${base}.`,
      `Use definitions, classifications, examples and consequences together when revising this topic.`,
      `Separate permanent textbook facts from current affairs; this page covers static syllabus knowledge only.`,
      `Check names, dates, places, Articles, units or terms carefully because they are common objective-question targets.`,
      `Relate the topic to nearby concepts in the same ${topic.moduleTitle} module.`
    ],
    key_points: [
      `Core topic: ${topic.topicName}.`,
      `Module: ${topic.moduleTitle}.`,
      `Tracker focus: ${base}.`,
      'Prefer exact textbook terminology in examination answers.',
      'Revise the topic through definition, example, comparison and consequence.'
    ],
    examples: [`A syllabus example connected with ${topic.topicName}.`, `A comparison or application based on ${base}.`],
    comparison_points: [`Distinguish the definition of ${topic.topicName} from related terms in ${topic.moduleTitle}.`, 'Use chronology, classification or cause–effect order where the question requires it.'],
    common_misconceptions: ['Treating a related term as an exact synonym without checking its scope.', 'Memorising an isolated fact without its period, place, category or consequence.'],
    exam_focus_points: [`Define ${topic.topicName} precisely.`, `Revise the listed focus areas: ${base}.`, 'Practise matching, statement-based and assertion–reason questions.']
  }));
}

function buildOfflinePayload(topic) {
  const curated = CURATED_CONTENT[topic.slug];
  if (!curated) throw new Error(`No manually authored content exists yet for ${topic.url}`);
  const concepts = curated.concepts;
  const title = curated.title;
  const introduction_points = curated.introduction_points;
  const concept_revisions = concepts.map((concept) => ({
    concept_id: concept.id,
    title: concept.title,
    definition_points: concept.explanation_points.slice(0, 3),
    must_remember: concept.key_points.slice(0, 5),
    exam_traps: concept.common_misconceptions.slice(0, 2)
  }));
  const manualQuiz = buildManualQuizQuestions(topic);
  const quiz_questions = manualQuiz.length ? manualQuiz : buildGenericQuizQuestions(topic, concepts);
  const topic_test = manualQuiz.length
    ? manualQuiz.filter((question) => ['mcq', 'assertion_reason', 'match_following', 'case_based'].includes(question.type)).slice(0, 10).map((question, index) => ({ ...question, id: `t-${String(index + 1).padStart(3, '0')}` }))
    : buildGenericTopicTest(topic, concepts);
  return { title, short_title: curated?.short_title || topic.topicName, introduction_points, movement_table: curated.movement_table || [], movement_table_meta: curated.movement_table_meta || {}, concepts, revision: { concept_revisions, quick_facts: concepts.flatMap((concept) => concept.key_points).slice(0, 10), glossary: concepts.map((concept) => ({ term: concept.title, definition: concept.lead })), comparisons: concepts.slice(0, 2).map((concept, index) => ({ left: concept.title, right: concepts[(index + 1) % concepts.length].title, difference_points: concept.comparison_points })), memory_hooks: concepts.slice(0, 3).map((concept) => `Remember ${concept.title}: ${concept.key_points[0]}`), exam_traps: concepts.flatMap((concept) => concept.common_misconceptions).slice(0, 8) }, quiz_questions, topic_test };
}

async function generateGeminiPayload(topic, ai) {
  const prompt = buildPrompt(topic);
  let activePrompt = prompt;
  let lastError;
  let lastRaw = '';
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    try {
      const response = await ai.models.generateContent({
        model: MODEL,
        contents: activePrompt,
        config: { temperature: 0.2, responseMimeType: 'application/json' }
      });
      if (!response?.text) throw new Error('Gemini returned an empty response');
      lastRaw = response.text;
      const data = parseJson(response.text);
      validatePayload(data, { deep: true });
      return { data, attempts: attempt, finalError: null, raw: response.text };
    } catch (error) {
      lastError = error;
      const status = Number(error?.status || error?.code || error?.error?.code || error?.response?.status) || 0;
      if ([400, 401, 403].includes(status) || attempt === maxAttempts) break;
      const waitMs = status === 429 ? Math.min(15000, attempt * 5000) : Math.min(12000, attempt * 3000);
      console.warn(`Gemini attempt ${attempt} failed (${status || error.message}); retrying in ${Math.round(waitMs / 1000)}s.`);
      const previousResponse = lastRaw ? `\n\nHere is the previous response. Preserve its accurate content and repair it instead of shortening it:\n${lastRaw}` : '';
      activePrompt = `${prompt}\n\nThe previous response failed validation or parsing: ${error.message}\nReturn a complete corrected JSON object. Add every missing field/item required by the schema, keep all existing concepts, and do not omit any question type.${previousResponse}`;
      await new Promise((resolve) => setTimeout(resolve, waitMs));
    }
  }
  const failure = new Error(lastError?.message || 'Gemini generation failed');
  failure.attempts = maxAttempts;
  throw failure;
}

function retryDelayMs(error, attempt) {
  const status = Number(error?.status || error?.code || error?.error?.code || error?.response?.status) || 0;
  if (status === 429) return Math.min(15000, 5000 * attempt);
  return error?.isValidationError ? 1500 * attempt : 2500 * attempt;
}

async function generatePayload(topic, ai) {
  if (CURATED_CONTENT[topic.slug]) {
    const data = buildOfflinePayload(topic);
    validatePayload(data);
    return { data, attempts: 0, finalError: null, raw: null, model: 'offline-curated' };
  }
  if (!ai) throw new Error(`No curated content exists for ${topic.url}; start with --gemini and GEMINI_API_KEY.`);
  const result = await generateGeminiPayload(topic, ai);
  return { ...result, model: MODEL };
}

function escapeHtml(value) {
  return String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function inlineText(value) { return escapeHtml(value).replace(/\n/g, '<br>'); }
function list(items, className = '') { return `<ul${className ? ` class="${className}"` : ''}>${(Array.isArray(items) ? items : []).map((item) => `<li>${inlineText(item)}</li>`).join('')}</ul>`; }
function safeArray(value, fallback = []) { return Array.isArray(value) ? value : fallback; }
function optionalList(title, items, className = 'notes-bullet-list') {
  const values = safeArray(items);
  return values.length ? `<h3>${escapeHtml(title)}</h3>${list(values, className)}` : '';
}

function renderConcepts(content) {
  const movementTable = renderMovementTable(content.movement_table, content.movement_table_meta);
  return `${movementTable}${safeArray(content.concepts).map((concept, index) => `<section class="notes-section" id="concept-${escapeHtml(concept.id || `concept-${index + 1}`)}">
    <div class="concept-number">Concept ${index + 1}${concept.learning_stage ? ` · ${escapeHtml(concept.learning_stage)}` : ''}</div>
    <h2>${escapeHtml(concept.title || 'Concept')}</h2>
    <p class="lead-concept">${inlineText(concept.lead || '')}</p>
    ${optionalList('Prerequisites', concept.prerequisite_points)}
    ${optionalList('Definitions and scope', concept.definition_points)}
    <h3>Step-by-step explanation</h3>${list(concept.explanation_points, 'notes-bullet-list')}
    <h3>Key points</h3>${list(concept.key_points, 'notes-bullet-list')}
    <div class="gk-callout"><strong>Worked examples</strong>${list(concept.worked_examples || concept.examples, 'notes-bullet-list')}</div>
    ${optionalList('Applications and connections', concept.applications)}
    ${optionalList('Advanced points, exceptions and limitations', concept.advanced_points, 'notes-bullet-list')}
    ${optionalList('Additional examples', concept.examples, 'notes-bullet-list')}
    <div class="comparison-callout"><strong>Important distinctions</strong>${list(concept.comparison_points, 'notes-bullet-list')}</div>
    <div class="trap-callout"><strong>Common misconceptions</strong>${list(concept.common_misconceptions, 'notes-bullet-list')}</div>
    <div class="exam-focus"><strong>Exam focus</strong>${list(concept.exam_focus_points, 'notes-bullet-list')}</div>
  </section>`).join('\n')}`;
}

function renderMovementTable(rows, meta = {}) {
  if (!Array.isArray(rows) || !rows.length) return '';
  const tableTitle = meta.title || 'Revolutionary Movements: Founders, Leaders and Key Points';
  const tableCaption = meta.caption || 'Revolutionary movements, founders, leaders, period and key points';
  const firstHeader = meta.first_header || 'Movement / organisation / action';
  const peopleHeader = meta.people_header || 'Founders / leaders';
  const keyHeader = meta.key_header || 'Key points';
  const cellStyle = 'padding:11px;border:1px solid #dfe5ec;vertical-align:top;text-align:left';
  const cell = (label, value, header = false) => header
    ? `<th scope="col" style="${cellStyle}">${escapeHtml(value)}</th>`
    : `<td data-label="${escapeHtml(label)}" style="${cellStyle}">${escapeHtml(value)}</td>`;
  const founderCell = (row) => row.founders
    ? `<strong class="founder-name">Founders: ${escapeHtml(row.founders)}</strong><br><span>Leaders: ${escapeHtml(row.leaders || '—')}</span>`
    : escapeHtml(row.leaders || '—');
  const rowsHtml = rows.map((row, index) => `<tr><td data-label="No." style="${cellStyle};text-align:center;font-weight:800;color:var(--accent,#b45309)">${index + 1}</td><th scope="row" data-label="${escapeHtml(firstHeader)}" style="${cellStyle};font-weight:800">${escapeHtml(row.movement)}</th>${cell('Period', row.period)}<td data-label="${escapeHtml(peopleHeader)}" style="${cellStyle}">${founderCell(row)}</td>${cell(keyHeader, row.key_points)}</tr>`).join('');
  return `<section class="movement-table-section" id="movement-table" aria-labelledby="movement-table-heading" style="margin:22px 0 28px;padding:20px;background:var(--surface,#fff);border:1px solid #dfe5ec;border-radius:14px"><style>.movement-table-section .movement-table th,.movement-table-section .movement-table td{overflow-wrap:anywhere}.movement-table-section .movement-table thead th{background:rgba(180,83,9,.07)}.movement-table-section .founder-name{color:var(--accent,#b45309);font-weight:900}@media (max-width:760px){.movement-table-section .table-scroll{overflow-x:visible}.movement-table-section .movement-table{min-width:0!important;width:100%!important}.movement-table-section .movement-table,.movement-table-section .movement-table tbody,.movement-table-section .movement-table tr,.movement-table-section .movement-table th,.movement-table-section .movement-table td{display:block}.movement-table-section .movement-table thead{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.movement-table-section .movement-table tr{margin:0 0 14px;border:1px solid #dfe5ec;border-radius:10px;overflow:hidden}.movement-table-section .movement-table th,.movement-table-section .movement-table td{border:0!important;border-bottom:1px solid #e7ebf0!important;padding:10px 12px!important}.movement-table-section .movement-table tr:last-child{margin-bottom:0}.movement-table-section .movement-table th[scope=row]{background:rgba(180,83,9,.07);font-size:1rem}.movement-table-section .movement-table td::before{content:attr(data-label);display:block;margin-bottom:3px;color:#5b6b7e;font-size:.72rem;font-weight:800;letter-spacing:.04em;text-transform:uppercase}}</style><h2 id="movement-table-heading">${escapeHtml(tableTitle)}</h2><div class="table-scroll" role="region" aria-label="${escapeHtml(tableTitle)}" tabindex="0" style="max-width:100%;overflow-x:auto;-webkit-overflow-scrolling:touch"><table class="movement-table" style="width:100%;min-width:100%;table-layout:fixed;border-collapse:collapse"><colgroup><col style="width:6%"><col style="width:22%"><col style="width:11%"><col style="width:27%"><col style="width:34%"></colgroup><caption>${escapeHtml(tableCaption)}</caption><thead><tr>${cell('', 'No.', true)}${cell('', firstHeader, true)}${cell('', 'Period', true)}${cell('', peopleHeader, true)}${cell('', keyHeader, true)}</tr></thead><tbody>${rowsHtml}</tbody></table></div></section>`;
}

function renderRevision(revision, title) {
  const glossary = safeArray(revision?.glossary).map((item) => `<div class="glossary-item"><strong>${escapeHtml(item.term)}</strong><span>${inlineText(item.definition)}</span></div>`).join('');
  const conceptRevisions = safeArray(revision?.concept_revisions).map((item, index) => `<section class="revision-card-box highlight"><div class="concept-number">Concept ${index + 1}</div><h2>${escapeHtml(item.title || 'Concept revision')}</h2><h3>Definition and scope</h3>${list(item.definition_points, 'must-remember-list')}<h3>Must remember</h3>${list(item.must_remember, 'must-remember-list')}<h3>Concept-specific exam traps</h3>${list(item.exam_traps, 'must-remember-list')}</section>`).join('');
  const comparisons = safeArray(revision?.comparisons).map((item) => `<div class="revision-comparison"><div><strong>${escapeHtml(item.left)}</strong><span>vs</span><strong>${escapeHtml(item.right)}</strong></div>${list(item.difference_points, 'must-remember-list')}</div>`).join('');
  return `<div class="summary-hero-box"><h2>Rapid revision: ${escapeHtml(title)}</h2><p>Review every concept point-wise before attempting the quiz and timed test.</p></div>${conceptRevisions}<section class="revision-card-box"><h2>Quick facts</h2>${list(revision?.quick_facts, 'must-remember-list')}</section><section class="revision-card-box"><h2>Glossary</h2><div class="glossary-grid">${glossary}</div></section><section class="revision-card-box"><h2>Important distinctions</h2><div class="revision-comparisons">${comparisons}</div></section><section class="revision-card-box"><h2>Memory hooks</h2>${list(revision?.memory_hooks, 'must-remember-list')}</section><section class="revision-card-box"><h2>Exam traps and cautions</h2>${list(revision?.exam_traps, 'must-remember-list')}</section>`;
}

const TYPE_NAMES = { mcq: 'MCQ', assertion_reason: 'Assertion–Reason', true_false: 'True / False', fill_blank: 'Fill in the blank', match_following: 'Match the following', case_based: 'Case-based', short_answer: 'Short answer' };
const LETTERS = ['A', 'B', 'C', 'D', 'E'];

function renderSourceData(question) {
  const accepted = safeArray(question.accepted_answers).map((answer) => `<span class="accepted-answer">${inlineText(answer)}</span>`).join('');
  const expected = question.expected_answer ? `<span class="expected-answer">${inlineText(question.expected_answer)}</span>` : '';
  return `<div class="question-source-data" aria-hidden="true">${accepted}${expected}<p class="question-explanation">${inlineText(question.explanation || '')}</p></div>`;
}

function renderQuizQuestion(question, index) {
  const type = question.type || 'mcq';
  let answerBody;
  if (type === 'fill_blank') answerBody = `<input class="quiz-answer-input" id="quiz-input-${index}" aria-label="Your answer"><button class="quiz-check-btn" data-fill="${index}">Check answer</button>`;
  else if (type === 'short_answer') answerBody = `<textarea class="quiz-answer-textarea" id="quiz-input-${index}" aria-label="Your answer"></textarea><button class="quiz-check-btn" data-short="${index}">Show answer</button>`;
  else answerBody = `<div class="quiz-options-group">${safeArray(question.options, ['Option A', 'Option B']).map((option, optionIndex) => `<button type="button" class="quiz-option-btn" data-quiz="${index}" data-option="${optionIndex}"><span class="option-letter">${LETTERS[optionIndex] || optionIndex + 1}</span><span class="option-text">${inlineText(option)}</span></button>`).join('')}</div>`;
  const correct = Number.isInteger(question.correct_index) ? ` data-correct="${question.correct_index}"` : '';
  return `<article class="quiz-question-card" id="quiz-card-${index}" data-index="${index}" data-type="${escapeHtml(type)}"${correct}><div class="q-header"><span class="q-number">Question ${index + 1}</span><span class="question-type">${escapeHtml(TYPE_NAMES[type] || type)}</span></div><p class="q-text">${inlineText(question.question || '')}</p>${answerBody}${renderSourceData(question)}<div id="quiz-feedback-${index}"></div></article>`;
}

function renderTestQuestion(question, index) {
  const type = question.type || 'mcq';
  return `<article class="test-question-card" id="test-card-${index}" data-index="${index}" data-correct="${Number.isInteger(question.correct_index) ? question.correct_index : 0}"><div class="test-q-header"><span class="t-badge">Question ${index + 1}</span><span class="question-type">${escapeHtml(TYPE_NAMES[type] || type)}</span></div><p class="test-question-text">${inlineText(question.question || '')}</p><div class="quiz-options-group">${safeArray(question.options, ['Option A', 'Option B']).map((option, optionIndex) => `<button type="button" class="test-option-btn quiz-option-btn" data-test="${index}" data-option="${optionIndex}"><span class="option-letter">${LETTERS[optionIndex] || optionIndex + 1}</span><span class="option-text">${inlineText(option)}</span></button>`).join('')}</div>${renderSourceData(question)}<div id="test-feedback-${index}"></div></article>`;
}

function safeJson(data) { return JSON.stringify(data ?? []).replace(/</g, '\\u003c').replace(/>/g, '\\u003e').replace(/&/g, '\\u0026'); }

function compileHtml(content, topic, failureNotice = '') {
  const canonical = `https://sjmaths.com${topic.url}`;
  const shortTitle = content.short_title || topic.topicName;
  const description = `${shortTitle}: point-wise ${topic.moduleTitle} study notes, concept quiz, revision summary and topic test for UP TGT and UP PGT preparation.`;
  const quiz = safeArray(content.quiz_questions);
  const test = safeArray(content.topic_test);
  const robots = failureNotice ? 'noindex,nofollow' : 'index,follow,max-snippet:-1,max-image-preview:large,max-video-preview:-1';
  const notice = failureNotice ? `<div class="generation-notice"><strong>Generation needs another run.</strong><span>${escapeHtml(failureNotice)}</span></div>` : '';
  return `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(content.title || topic.topicName)} | ${escapeHtml(topic.moduleTitle)} | SJ Maths</title><meta name="description" content="${escapeHtml(description)}"><meta name="robots" content="${robots}"><meta name="author" content="SJ Maths"><meta name="theme-color" content="#16324f"><link rel="canonical" href="${canonical}"><link rel="icon" type="image/png" href="/favicon.png"><meta property="og:type" content="article"><meta property="og:site_name" content="SJ Maths"><meta property="og:title" content="${escapeHtml(content.title || topic.topicName)} | ${escapeHtml(topic.moduleTitle)}"><meta property="og:description" content="${escapeHtml(description)}"><meta property="og:url" content="${canonical}"><meta property="og:image" content="https://sjmaths.com/assets/images/og-default.jpg"><meta name="twitter:card" content="summary"><meta name="twitter:title" content="${escapeHtml(content.title || topic.topicName)} | ${escapeHtml(topic.moduleTitle)}"><meta name="twitter:description" content="${escapeHtml(description)}"><script type="application/ld+json">${safeJson({'@context':'https://schema.org','@type':'LearningResource',name:content.title || topic.topicName,headline:content.title || topic.topicName,description,url:canonical,educationalLevel:'UP TGT and UP PGT',learningResourceType:'Study guide',isPartOf:{'@type':'WebSite',name:'SJ Maths',url:'https://sjmaths.com/'}})}</script><link rel="stylesheet" href="/assets/css/topic-page.min.css?v=718ef3ff"><style>:root{--brand:#16324f;--brand-dark:#0f2439;--accent:#b45309;--accent-hover:#92400e;--accent-soft:rgba(180,83,9,.09);--accent-border:rgba(180,83,9,.26)}body{background:radial-gradient(circle at 100% 0,rgba(180,83,9,.06),transparent 28rem),var(--bg,#f6f8fb)}.study-tabs{grid-template-columns:repeat(4,minmax(0,1fr))}.tab-btn{min-height:54px}.tab-panel.hidden,.question-source-data,.hidden{display:none!important}.concept-number{display:inline-block;margin-bottom:8px;color:var(--accent);font-size:.74rem;font-weight:900;text-transform:uppercase;letter-spacing:.08em}.lead-concept{font-weight:700;color:var(--brand);font-size:1rem}.notes-section h3{margin-top:18px;color:var(--brand);font-size:1rem}.gk-callout,.comparison-callout,.trap-callout,.exam-focus{padding:14px 16px;border-radius:10px;margin:14px 0;line-height:1.6}.gk-callout{background:#eff6ff;border-left:4px solid #2563eb}.comparison-callout{background:#f0fdf4;border-left:4px solid #15803d}.trap-callout{background:#fffbeb;border-left:4px solid #d97706}.exam-focus{background:var(--accent-soft);border-left:4px solid var(--accent);color:var(--ink2)}.question-type{display:inline-flex;padding:3px 9px;border-radius:999px;background:var(--accent-soft);color:var(--accent);font-size:.72rem;font-weight:850;text-transform:uppercase;letter-spacing:.04em}.quiz-answer-input,.quiz-answer-textarea{width:100%;padding:11px 13px;border:1px solid var(--line);border-radius:9px;background:var(--paper);color:var(--ink);font:inherit}.quiz-answer-textarea{min-height:96px;resize:vertical}.quiz-check-btn{margin-top:10px;padding:9px 14px;border:0;border-radius:8px;background:var(--brand);color:#fff;font-weight:800;cursor:pointer}.revision-comparisons{display:flex;flex-direction:column;gap:12px}.revision-comparison{padding:14px 16px;border:1px solid var(--line);border-radius:10px;background:var(--paper-card)}.revision-comparison>div{display:flex;gap:9px;align-items:center;flex-wrap:wrap;color:var(--brand)}.revision-comparison span{color:var(--muted);font-size:.78rem}.test-question-card .test-option-btn{width:100%;text-align:left}.generation-notice{margin:16px 0;padding:14px 16px;border:1px solid #f59e0b;border-left:4px solid #d97706;border-radius:10px;background:#fffbeb;color:#78350f;display:grid;gap:4px}@media(max-width:680px){.study-tabs{grid-template-columns:repeat(2,minmax(0,1fr))}.tab-btn{font-size:.78rem}.tab-btn span:first-child{display:none}}</style></head>
<body><header class="site-header"><div class="wrap header-inner"><a class="brand" href="https://sjmaths.com/"><span class="brand-mark" style="background:linear-gradient(145deg,#16324f,#b45309);font-family:serif;font-size:1.35rem;font-style:italic;display:flex;align-items:center;justify-content:center">&int;</span><span><span class="brand-name">SJ Maths</span><span class="brand-sub">UP TGT PGT General Knowledge</span></span></a><div class="header-actions"><button type="button" class="theme-toggle-btn" id="btn-theme-toggle" aria-label="Toggle dark mode">Dark Mode</button><a class="back-btn" href="/up-tgt-pgt-gk/${escapeHtml(topic.module)}/">← ${escapeHtml(topic.moduleTitle)}</a></div></div></header>
<main class="wrap"><section class="hero"><nav class="breadcrumb" aria-label="Breadcrumb"><a href="https://sjmaths.com/">Home</a><span>›</span><a href="/up-tgt-pgt-gk/">UP TGT PGT GK</a><span>›</span><a href="/up-tgt-pgt-gk/${escapeHtml(topic.module)}/">${escapeHtml(topic.moduleTitle)}</a><span>›</span><span aria-current="page">${escapeHtml(shortTitle)}</span></nav><div class="kicker">${escapeHtml(topic.moduleTitle)}</div><h1>${escapeHtml(content.title || topic.topicName)}</h1><p class="lead">${escapeHtml(safeArray(content.introduction_points, [topic.description || topic.topicName])[0])}</p><div class="exam-badges"><a class="exam-chip pgt" href="/up-tgt-pgt-gk/">UP TGT PGT GK</a><span class="exam-chip both">${safeArray(content.concepts).length} concepts</span><span class="exam-chip both">${quiz.length} quiz questions</span><span class="exam-chip both">${test.length}-question test</span></div></section>${notice}<div class="study-tabs-sticky-wrapper"><div class="study-tabs" role="tablist" aria-label="GK study tabs"><button type="button" class="tab-btn active" role="tab" aria-selected="true" data-tab="tab-notes" id="tab-btn-notes"><span>📖</span><span>Study Notes</span></button><button type="button" class="tab-btn" role="tab" aria-selected="false" data-tab="tab-quiz" id="tab-btn-quiz"><span>❓</span><span>Concept Quiz</span><span class="tab-badge">${quiz.length}Q</span></button><button type="button" class="tab-btn" role="tab" aria-selected="false" data-tab="tab-summary" id="tab-btn-summary"><span>⚡</span><span>Revision Summary</span></button><button type="button" class="tab-btn" role="tab" aria-selected="false" data-tab="tab-test" id="tab-btn-test"><span>⏱️</span><span>Topic Test</span><span class="tab-badge">${test.length}Q</span></button></div></div><div class="main-grid"><div class="content-col"><article class="tab-panel active" id="tab-notes" role="tabpanel" aria-labelledby="tab-btn-notes"><div class="card"><h2>Topic overview</h2>${list(content.introduction_points, 'notes-bullet-list')}</div>${renderConcepts(content)}<nav class="topic-pagination" aria-label="Topic navigation"><a class="topic-nav-btn next" href="/up-tgt-pgt-gk/${escapeHtml(topic.module)}/"><span>Module tracker →</span><strong>${escapeHtml(topic.moduleTitle)}</strong></a></nav></article><article class="tab-panel hidden" id="tab-quiz" role="tabpanel" aria-labelledby="tab-btn-quiz"><div class="quiz-panel-header"><div class="quiz-panel-title"><h2>Concept Quiz</h2><p>Practice every concept with multiple question formats.</p></div><div class="quiz-live-scoreboard"><span class="score-pill" id="quiz-score">Score: 0 / ${quiz.length}</span><button type="button" class="btn-reset-quiz" id="btn-reset-quiz">Reset</button></div></div><div class="quiz-questions-list" id="quiz-container">${quiz.map(renderQuizQuestion).join('')}</div></article><article class="tab-panel hidden" id="tab-summary" role="tabpanel" aria-labelledby="tab-btn-summary"><div class="summary-container">${renderRevision(content.revision, shortTitle)}</div></article><article class="tab-panel hidden" id="tab-test" role="tabpanel" aria-labelledby="tab-btn-test"><div class="test-panel-header"><div><h2>Timed Topic Test</h2><p>Ten objective questions. The timer starts when you open this tab.</p></div><span class="test-timer-badge" id="test-timer">10:00</span></div><div class="test-questions-list" id="test-container">${test.map(renderTestQuestion).join('')}</div><div class="test-submit-bar"><button type="button" class="btn-submit-test" id="btn-submit-test">Submit Test</button></div><div class="test-result-modal hidden" id="test-result"><div class="result-card"><h3>Test Result</h3><div class="result-score-circle"><span id="test-score">0</span> / ${test.length || 10}</div><p id="test-feedback">Review the explanations and retry when ready.</p><button type="button" class="btn-retake-test" id="btn-retake-test">Retake Test</button></div></div></article></div><aside class="sidebar-col"><div class="sidebar-card side-card"><div class="side-card-header"><span class="side-badge">GK module</span><h3>${escapeHtml(topic.moduleTitle)}</h3></div><p class="side-desc">Point-wise notes, concept practice, revision and a timed test for this static GK topic.</p><div class="side-action-box" style="margin-top:1.5rem"><a class="side-action-btn" href="/up-tgt-pgt-gk/${escapeHtml(topic.module)}/" style="background:#16324f;display:block;text-align:center;padding:10px;color:#fff;border-radius:8px;font-weight:600">Open module tracker →</a></div></div></aside></div></main><footer class="site-footer"><div class="wrap footer-inner"><div><p><strong>SJ Maths — UP TGT PGT GK</strong></p><p>Structured preparation for static General Knowledge subjects.</p></div><div class="footer-links"><a href="https://sjmaths.com/">Home</a><a href="/up-tgt-pgt-gk/">UP TGT PGT GK</a></div></div></footer>
<script type="application/json" id="quiz-data">${safeJson(quiz)}</script><script type="application/json" id="test-data">${safeJson(test)}</script><script>
document.addEventListener('DOMContentLoaded',()=>{const esc=v=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');const quiz=JSON.parse(document.getElementById('quiz-data').textContent||'[]');const test=JSON.parse(document.getElementById('test-data').textContent||'[]');const typeNames=${safeJson(TYPE_NAMES)};const letters=['A','B','C','D','E'];let quizScore=0;const answered=new Set();const feedback=(ok,text)=>'<div class="quiz-feedback '+(ok?'correct':'incorrect')+'"><strong>'+(ok?'✓ Correct':'✗ Review')+'</strong><p>'+esc(text)+'</p></div>';function markQuiz(i,ok,text){if(answered.has(i))return;answered.add(i);if(ok)quizScore++;const card=document.getElementById('quiz-card-'+i);card.dataset.answered='true';card.querySelectorAll('button').forEach(b=>b.disabled=true);document.getElementById('quiz-feedback-'+i).innerHTML=feedback(ok,text);document.getElementById('quiz-score').textContent='Score: '+quizScore+' / '+quiz.length;}document.querySelectorAll('[data-quiz]').forEach(btn=>btn.addEventListener('click',()=>{const i=Number(btn.dataset.quiz),o=Number(btn.dataset.option),q=quiz[i];document.querySelectorAll('#quiz-card-'+i+' [data-option]').forEach((b,n)=>{b.disabled=true;if(n===q.correct_index)b.classList.add('correct');if(n===o&&o!==q.correct_index)b.classList.add('incorrect');});markQuiz(i,o===q.correct_index,q.explanation);}));document.querySelectorAll('[data-fill]').forEach(btn=>btn.addEventListener('click',()=>{const i=Number(btn.dataset.fill),q=quiz[i],v=document.getElementById('quiz-input-'+i).value.trim().toLowerCase();markQuiz(i,(q.accepted_answers||[]).some(a=>v===String(a).trim().toLowerCase()),'Accepted answer(s): '+(q.accepted_answers||[]).join(', ')+' — '+q.explanation);}));document.querySelectorAll('[data-short]').forEach(btn=>btn.addEventListener('click',()=>{const i=Number(btn.dataset.short),q=quiz[i];markQuiz(i,false,'Expected answer: '+(q.expected_answer||'See the explanation')+' — '+q.explanation);}));document.getElementById('btn-reset-quiz').addEventListener('click',()=>location.reload());const chosen={};let submitted=false;document.querySelectorAll('[data-test]').forEach(btn=>btn.addEventListener('click',()=>{if(submitted)return;const i=Number(btn.dataset.test);chosen[i]=Number(btn.dataset.option);document.querySelectorAll('#test-card-'+i+' [data-option]').forEach(b=>b.classList.remove('selected'));btn.classList.add('selected');}));function submitTest(){if(submitted)return;submitted=true;let score=0;test.forEach((q,i)=>{const answer=chosen[i];if(answer===q.correct_index)score++;document.querySelectorAll('#test-card-'+i+' [data-option]').forEach((b,n)=>{b.disabled=true;if(n===q.correct_index)b.classList.add('correct');if(n===answer&&answer!==q.correct_index)b.classList.add('incorrect');});document.getElementById('test-feedback-'+i).innerHTML=feedback(answer===q.correct_index,q.explanation);});document.getElementById('test-score').textContent=score;document.getElementById('test-result').classList.remove('hidden');document.getElementById('btn-submit-test').classList.add('hidden');}document.getElementById('btn-submit-test').addEventListener('click',submitTest);document.getElementById('btn-retake-test').addEventListener('click',()=>location.reload());let timer=null,remaining=600;function startTimer(){if(timer||submitted)return;timer=setInterval(()=>{remaining--;document.getElementById('test-timer').textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0');if(remaining<=0){clearInterval(timer);submitTest();}},1000);}const tabs=document.querySelectorAll('.tab-btn'),panels=document.querySelectorAll('.tab-panel');tabs.forEach(btn=>btn.addEventListener('click',()=>{tabs.forEach(b=>{b.classList.remove('active');b.setAttribute('aria-selected','false');});panels.forEach(p=>{p.classList.remove('active');p.classList.add('hidden');});btn.classList.add('active');btn.setAttribute('aria-selected','true');document.getElementById(btn.dataset.tab).classList.remove('hidden');document.getElementById(btn.dataset.tab).classList.add('active');if(btn.dataset.tab==='tab-test')startTimer();window.scrollTo({top:document.querySelector('.study-tabs-sticky-wrapper').offsetTop-15,behavior:'smooth'});}));const theme=document.getElementById('btn-theme-toggle');const saved=localStorage.getItem('sjmaths_theme')||localStorage.getItem('sj_theme');if(saved==='dark'){document.body.classList.add('dark-mode');document.documentElement.classList.add('dark');theme.textContent='Light Mode';}theme.addEventListener('click',()=>{const dark=document.body.classList.toggle('dark-mode');document.documentElement.classList.toggle('dark',dark);localStorage.setItem('sjmaths_theme',dark?'dark':'light');localStorage.setItem('sj_theme',dark?'dark':'light');theme.textContent=dark?'Light Mode':'Dark Mode';});});</script></body></html>`;
}

function renderFallback(topic, parsed, error) {
  const data = parsed && typeof parsed === 'object' ? parsed : {};
  const concepts = safeArray(data.concepts).map((concept, index) => ({
    id: concept.id || `concept-${index + 1}`,
    title: concept.title || `Concept ${index + 1}`,
    lead: concept.lead || '',
    explanation_points: safeArray(concept.explanation_points), key_points: safeArray(concept.key_points), examples: safeArray(concept.examples), comparison_points: safeArray(concept.comparison_points), common_misconceptions: safeArray(concept.common_misconceptions), exam_focus_points: safeArray(concept.exam_focus_points)
  }));
  return { title: data.title || topic.topicName, short_title: data.short_title || topic.topicName, introduction_points: safeArray(data.introduction_points, [topic.description || topic.topicName]), concepts, revision: data.revision || { concept_revisions: [], quick_facts: [], glossary: [], comparisons: [], memory_hooks: [], exam_traps: [] }, quiz_questions: safeArray(data.quiz_questions), topic_test: safeArray(data.topic_test) };
}

async function processTopic(topic, status, ai) {
  const indexPath = path.join(urlToDir(topic.url), 'index.html');
  if (!force && status[topic.url]?.status === 'completed' && status[topic.url]?.contentVersion === CONTENT_VERSION) {
    console.log(`Skipped ${topic.url} (already completed; use --force to regenerate)`);
    return;
  }
  console.log(`\nGenerating static GK page: ${topic.url} — ${topic.topicName}`);
  const topicModel = CURATED_CONTENT[topic.slug] ? 'offline-curated' : MODEL;
  status[topic.url] = { status: 'generating', model: topicModel, module: topic.module, startedAt: new Date().toISOString() }; writeStatus(status);
  const result = await generatePayload(topic, ai);
  const succeeded = result.data && !result.finalError;
  const content = succeeded ? result.data : renderFallback(topic, result.data, result.finalError);
  const failureNotice = succeeded ? '' : `The last generation attempt was saved after ${result.attempts} attempts. Validation error: ${result.finalError?.message || 'incomplete response'}`;
  fs.mkdirSync(path.dirname(indexPath), { recursive: true });
  fs.writeFileSync(indexPath, compileHtml(content, topic, failureNotice), 'utf8');
  if (succeeded) {
    status[topic.url] = { status: 'completed', contentVersion: CONTENT_VERSION, model: result.model || topicModel, module: topic.module, title: content.title, concepts: content.concepts.length, quizQuestions: content.quiz_questions.length, testQuestions: content.topic_test.length, attempts: result.attempts, completedAt: new Date().toISOString() };
    console.log(`  ✓ saved ${indexPath} (${content.concepts.length} concepts, ${content.quiz_questions.length} quiz questions)`);
  } else {
    status[topic.url] = { status: 'failed-last-attempt-saved', model: MODEL, module: topic.module, error: result.finalError?.message || 'incomplete response', attempts: result.attempts, savedAt: new Date().toISOString() };
    console.error(`  ✗ ${topic.url}: ${failureNotice}`);
  }
  writeStatus(status);
}

async function main() {
  const allTopics = discoverTopics();
  const targets = resolveTargets(allTopics);
  console.log(`Discovered ${targets.length} static GK topic(s). Current Affairs excluded. Model: ${MODEL}`);
  if (dryRun) { targets.forEach((topic) => console.log(`${topic.url} — ${topic.moduleTitle} — ${topic.topicName}`)); return; }
  const status = readStatus();
  let ai = null;
  if (useGemini) {
    const apiKey = process.env.GEMINI_API_KEY || process.env.GEMINI_API_KEY_1 || process.env.GOOGLE_API_KEY;
    if (!apiKey) throw new Error('Set GEMINI_API_KEY, GEMINI_API_KEY_1 or GOOGLE_API_KEY before using --gemini/--all.');
    ai = new GoogleGenAI({ apiKey });
  }
  for (const topic of targets) {
    try { await processTopic(topic, status, ai); }
    catch (error) { status[topic.url] = { status: 'failed', model: MODEL, module: topic.module, error: error.message, failedAt: new Date().toISOString() }; writeStatus(status); console.error(`  ✗ ${topic.url}: ${error.message}`); if (requestedTopic) throw error; }
    if (gapMs) await new Promise((resolve) => setTimeout(resolve, gapMs));
  }
  console.log(`Finished static GK generation with ${useGemini ? MODEL : 'offline-curated content'}. Current Affairs was not included.`);
}

main().catch((error) => { console.error(`Generation failed: ${error.message}`); process.exitCode = 1; });
